def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

n = 15925
factors = prime_factorization(n)
print(f"Prime factorization of {n}: {factors}")

def factorize(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_n_12(n, factorization):
    # tau(n^12) = product (12*a_i + 1)
    if n == 1:
        return 1
    tau = 1
    for prime, exponent in factorization.items():
        tau *= (12 * exponent + 1)
    return tau

n_candidate = 15925
factorization = factorize(n_candidate)
print(f"Prime factorization of {n_candidate}: {factorization}")

tau_result = tau_n_12(n_candidate, factorization)
print(f"tau({n_candidate}^12) = {tau_result}")

if tau_result == n_candidate:
    print("The candidate solution is correct.")
else:
    print("The candidate solution is incorrect.")

